CustomField.formula:
IF(
    /* Eligibility check not performed */
    OR(
        AND(
            NOT(ISBLANK(Applicant1PersonalHealthNumber__c)),
            ISBLANK(TEXT(Applicant1MSPStatus__c))
        ),
        AND(
            NOT(ISBLANK(Applicant2PersonalHealthNumber__c)),
            ISBLANK(TEXT(Applicant2MSPStatus__c))
        )
    ),
    "Eligibility check not performed on at least 1 applicant",

    /* At least one person not enrolled */
    IF(
        OR(
            AND(
                NOT(ISBLANK(Applicant1PersonalHealthNumber__c)),
                TEXT(Applicant1MSPStatus__c) = "Not Enrolled"
            ),
            AND(
                NOT(ISBLANK(Applicant2PersonalHealthNumber__c)),
                TEXT(Applicant2MSPStatus__c) = "Not Enrolled"
            )
        ),
        "At least one person is not enrolled",

        /* All enrolled */
        "All Enrolled"
    )
)
